/* Theme-toggle sweep, driven by the View Transitions API (see the click
   handler in Footer.astro). The browser snapshots the page before and after
   the .dark class toggles into ::view-transition-old(root) and
   ::view-transition-new(root); overriding the default cross-fade and masking
   the new-theme screenshot reveals it as a sweeping band, with the old
   screenshot sitting untouched underneath — so each side of the sweep is
   already showing its correct final theme.

   A mask (rather than the clip-path this used to use) is what makes the
   pixelated edge possible: clip-path can only describe a hard geometric
   shape, whereas a mask's edge is whatever image you feed it. */
::view-transition-old(root),
::view-transition-new(root) {
  animation: none;
  mix-blend-mode: normal;
}

::view-transition-old(root) {
  z-index: 1;
}

::view-transition-new(root) {
  z-index: 2;
}

[data-theme-sweep-direction="light"]::view-transition-new(root) {
  animation: theme-sweep-up var(--theme-sweep-duration) ease-in-out forwards;
}

[data-theme-sweep-direction="dark"]::view-transition-new(root) {
  animation: theme-sweep-down var(--theme-sweep-duration) ease-in-out forwards;
}

/* The mask image is a hard-stop gradient sized to twice the viewport height,
   so sliding it a full 100% moves the edge cleanly from one side of the
   screen to the other. Animating mask-position (not mask-size) keeps the
   pattern's scale fixed throughout — important once the dither lands, since
   animating the size would visibly stretch the cells mid-sweep. */
@keyframes theme-sweep-up {
  from {
    mask-image: linear-gradient(to top, #000 0 50%, transparent 50% 100%);
    mask-size: 100% 200%;
    mask-repeat: no-repeat;
    mask-position: 0 200%;
  }
  to {
    mask-image: linear-gradient(to top, #000 0 50%, transparent 50% 100%);
    mask-size: 100% 200%;
    mask-repeat: no-repeat;
    mask-position: 0 100%;
  }
}

@keyframes theme-sweep-down {
  from {
    mask-image: linear-gradient(to bottom, #000 0 50%, transparent 50% 100%);
    mask-size: 100% 200%;
    mask-repeat: no-repeat;
    mask-position: 0 -100%;
  }
  to {
    mask-image: linear-gradient(to bottom, #000 0 50%, transparent 50% 100%);
    mask-size: 100% 200%;
    mask-repeat: no-repeat;
    mask-position: 0 0%;
  }
}

