input.new_string:
/* Three stacked mask layers, composited together:

     1. SOLID + BAND (linear-gradient) — opaque across everything the sweep
        has already passed, then a --dither-band-tall ramp down to
        transparent. Sized to 200% of the viewport so sliding it a full 100%
        carries the edge cleanly from one side of the screen to the other.
     2. + 3. CHECKERBOARDS (conic-gradients) — two tiled 2x2 checkers at
        coprime cell sizes. `intersect` confines them to layer 1, and because
        the two never line up, the cells they knock out of the ramp look
        irregular rather than like a chessboard.

   The ramp in layer 1 is what turns a uniform speckle strip into a dissolve:
   where the gradient is near-opaque the checkers barely register, and where
   it fades out they punch through, so cell density falls off across the band.

   Only mask-position is animated (see the keyframes below) — animating
   mask-size instead would stretch the cells visibly mid-sweep. */
[data-theme-sweep-direction]::view-transition-new(root) {
  mask-size:
    100% 200%,
    var(--dither-cell) var(--dither-cell),
    var(--dither-cell-alt) var(--dither-cell-alt);
  mask-repeat: no-repeat, repeat, repeat;
  mask-composite: intersect;
  animation-duration: var(--theme-sweep-duration);
  animation-timing-function: linear;
  animation-fill-mode: forwards;
}

[data-theme-sweep-direction="light"]::view-transition-new(root) {
  mask-image:
    linear-gradient(
      to top,
      #000 0 calc(50% - var(--dither-band)),
      transparent 50%
    ),
    conic-gradient(
      #000 0 25%,
      transparent 25% 50%,
      #000 50% 75%,
      transparent 75%
    ),
    conic-gradient(
      #000 0 25%,
      transparent 25% 50%,
      #000 50% 75%,
      transparent 75%
    );
  animation-name: theme-sweep-up;
}

[data-theme-sweep-direction="dark"]::view-transition-new(root) {
  mask-image:
    linear-gradient(
      to bottom,
      #000 0 calc(50% - var(--dither-band)),
      transparent 50%
    ),
    conic-gradient(
      #000 0 25%,
      transparent 25% 50%,
      #000 50% 75%,
      transparent 75%
    ),
    conic-gradient(
      #000 0 25%,
      transparent 25% 50%,
      #000 50% 75%,
      transparent 75%
    );
  animation-name: theme-sweep-down;
}

/* Only the first (gradient) layer travels; the checkerboards stay pinned so
   cells hold still and wink on and off in place as the ramp passes over
   them, rather than the whole grid sliding down the screen with the edge. */
@keyframes theme-sweep-up {
  from {
    mask-position:
      0 200%,
      0 0,
      0 0;
  }
  to {
    mask-position:
      0 100%,
      0 0,
      0 0;
  }
}

@keyframes theme-sweep-down {
  from {
    mask-position:
      0 -100%,
      0 0,
      0 0;
  }
  to {
    mask-position:
      0 0%,
      0 0,
      0 0;
  }
}

