/* ONE mask layer, not two. The tile contains the whole edge — empty rows,
   then the dithered ramp, then solid rows — so the cells and the boundary
   they belong to can never drift apart.

   An earlier version split these into a solid gradient plus a separate noise
   strip. That failed twice over. Percentage mask-position resolves against
   (container - image), so a 200%-tall layer and a 120px-tall layer move at
   different rates from the same percentages and desynced — the dither ended
   up trailing on the wrong side of the edge. And `mask-composite: add` can
   only ever *add* cells outside the solid layer, never carve into it, so the
   boundary stayed a hard straight line no matter what the noise did.

   With one image the ramp IS the edge: there's no separate hard stop left to
   show through.

   Positions are in px/vh rather than percentages, because percentage
   mask-position is interpolated across (container - image) rather than being
   a plain offset — easy to reason about wrongly, as above. Absolute units
   just work.

   Height is fixed at the tile's natural cell size and only mask-position
   animates; animating mask-size would stretch the cells visibly mid-sweep. */
[data-theme-sweep-direction]::view-transition-new(root) {
  mask-size: calc(var(--dither-cell) * 64) var(--dither-tile-height);
  mask-repeat: repeat-x;
  /* The tile is 64x14 actual pixels blown up so each maps to one
     --dither-cell square; without this the browser smooths the upscale and
     the cells turn to mush. */
  image-rendering: pixelated;
  animation-duration: var(--theme-sweep-duration);
  animation-timing-function: linear;
  animation-fill-mode: forwards;
}

[data-theme-sweep-direction="light"]::view-transition-new(root) {
  mask-image: var(--dither-noise-flipped);
  animation-name: theme-sweep-up;
}

[data-theme-sweep-direction="dark"]::view-transition-new(root) {
  mask-image: var(--dither-noise);
  animation-name: theme-sweep-down;
}

/* The tile travels a full viewport height plus its own height, so it starts
   fully clear of one edge and ends fully clear of the other.

   Going dark the solid end leads from the top, so the tile starts just above
   the viewport and travels down. Going light it's mirrored: the solid end
   leads from the bottom, starting just below and travelling up. */
@keyframes theme-sweep-down {
  from {
    mask-position: 0 calc(-1 * var(--dither-tile-height));
  }
  to {
    mask-position: 0 100vh;
  }
}

@keyframes theme-sweep-up {
  from {
    mask-position: 0 100vh;
  }
  to {
    mask-position: 0 calc(-1 * var(--dither-tile-height));
  }
}

