  mask-image: var(--dither-noise), linear-gradient(#000, #000);
  animation-name: theme-sweep-down;
}

/* Two layers, but unlike the earlier broken version the solid one's edge is
   never visible: it's pinned to sit exactly under the tile's solid rows and
   extend away from the leading edge, so the only boundary on screen is the
   dithered one. The tile alone can't do this — it's only 14 cells tall, so
   with nothing behind it the revealed region would slide off with it and the
   new theme would vanish at the end of the sweep.

   Both layers move in lockstep off the same distance, in px/vh rather than
   percentages. (Percentage mask-position is interpolated across
   container - image, so layers of different heights move at different rates
   from identical values — exactly what desynced the earlier attempt.)

   Going dark the solid end leads from the top: the tile starts above the
   viewport and travels down, trailing dither behind it. Going light is the
   mirror image. */
@keyframes theme-sweep-down {
  from {
    mask-position:
      0 calc(-1 * var(--dither-tile-height)),
      0 calc(-100vh - var(--dither-tile-height) + var(--dither-cell) * 11);
  }
  to {
    mask-position:
      0 100vh,
      0 calc(0vh + var(--dither-cell) * 11);
  }
}

@keyframes theme-sweep-up {
  from {
    mask-position:
      0 100vh,
      0 calc(100vh + var(--dither-cell) * 3);
  }
  to {
    mask-position:
      0 calc(-1 * var(--dither-tile-height)),
      0 calc(-100vh + var(--dither-cell) * 3 - var(--dither-tile-height));
  }
}

